import os, glob, hashlib

pattern = "/home/andrea-zabala-c/Downloads/**/*.png"
pngs = glob.glob(pattern, recursive=True)
print(f"Total PNGs searched in Downloads: {len(pngs)}")

# Look for files ending with -001.png, -003.png, -005.png etc
doc_pages = {}
for p in pngs:
    bname = os.path.basename(p)
    if "_img-" in bname or "-00" in bname:
        parts = bname.rsplit("-", 1)
        if len(parts) == 2:
            base = parts[0]
            page = parts[1]
            doc_pages.setdefault(base, []).append((page, p))

print(f"\nFound {len(doc_pages)} document sets:")
for base, pages in list(doc_pages.items())[:10]:
    if len(pages) > 1:
        print(f"\n--- Document: {base} ---")
        hashes = []
        for pg, path in sorted(pages):
            sz = os.path.getsize(path)
            h = hashlib.sha256(open(path, "rb").read()).hexdigest()[:16]
            hashes.append(h)
            print(f"  Page/Layer {pg}: Size={sz} bytes, SHA256={h}")
        if len(set(hashes)) == 1:
            print("  ==> TODAS LAS CAPAS/MÁSCARAS DENTRO DEL MISMO DOCUMENTO SON 100% IDÉNTICAS EN HASH")
        else:
            print("  ==> LAS CAPAS/MÁSCARAS DENTRO DEL MISMO DOCUMENTO TIENEN HASHES DIFERENTES")
